"""Author original bounded skills lessons. No model calls or private CA/PA sources."""
import hashlib,json,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
LESSONS=[]
def add(feature,id,title,level,rule,example,prompt,right,wrong,explanation,task,day=None,wrong_feedback=None):
    if wrong_feedback is not None:
        assert len(wrong_feedback)==len(wrong)==3, 'Explain each distractor once'
        assert all(isinstance(text,str) and len(text)>25 for text in wrong_feedback), 'Use a meaningful choice explanation'
    options=[right,*wrong]
    position=int(hashlib.sha256(id.encode()).hexdigest()[:8],16)%4
    options=options[position:]+options[:position]
    feedback=[explanation,*wrong_feedback] if wrong_feedback is not None else None
    if feedback is not None:
        feedback=feedback[position:]+feedback[:position]
    LESSONS.append(dict(feature=feature,id=id,title=title,level=level,explanation=rule,example=example,
        check=dict(id=id+'-check',prompt=prompt,options=options,answer=options.index(right),explanation=explanation),
        task=task,grammar_day=day,attribution='Original CSS Vista instructional example; not an authentic past-paper question.'))
    if feedback is not None:
        LESSONS[-1]['check']['option_feedback']=feedback

S=[
('sentence-core','A complete sentence','beginner','A sentence expresses a complete thought. Find who or what the sentence is about, then what that subject does or is. An imperative may have an understood subject: you.','The researcher checked the figures. Subject: the researcher. Predicate: checked the figures.','Which sentence expresses a complete thought?','The committee published its report.',['Because the report was late.','The report on the desk.','After checking the figures.'],'The subject committee has a finite verb, published, and the thought is complete.','Write one sentence about an action you completed today. Underline the subject mentally and identify its verb.',2),
('subject-predicate','Subject and predicate','beginner','The subject identifies the person or thing discussed. The predicate says something about it. Extra words inside a subject do not change its head noun.','The books on the upper shelf belong to Sara. Books is the head noun; belong to Sara is the predicate.','Which is the head of the subject in "The quality of the reports matters"?','quality',['reports','matters','of'],'Quality is the head noun; of the reports describes it.','Write a sentence whose subject includes an of phrase. Make the verb agree with the head noun.',2),
('sentence-types','Simple, compound and complex sentences','beginner','A simple sentence has one independent clause. A compound sentence joins independent clauses. A complex sentence includes an independent clause and at least one dependent clause. Length alone does not determine the type.','The class ended, but the students stayed. Both clauses can stand alone.','Which example is complex?','Although the class ended, the students stayed.',['The students stayed.','The class ended, and the students stayed.','The attentive students stayed quietly.'],'Although introduces a dependent clause; the students stayed is independent.','Write a simple sentence, then revise it to show a condition using if or a contrast using although.',3),
('fragments','Repairing fragments','beginner','A dependent clause cannot normally stand alone in formal prose. Attach it to an independent clause, or remove the dependency while preserving meaning.','Fragment: Because the road was closed. Complete: We returned because the road was closed.','Which repair is complete?','We postponed the visit because the road was closed.',['Because the road was closed.','The closed road near the village.','Although the road was closed.'],'The repair supplies an independent clause with a subject and a finite verb.','Repair this fragment in your own way: "Although the proposal was promising." Do not invent evidence about a real proposal.',4),
('run-ons','Run-ons and comma splices','beginner','Two independent clauses need suitable punctuation or a conjunction. A comma alone usually cannot join them. Choose a boundary that reflects their relationship.','Comma splice: The room was crowded, we waited outside. Repair: The room was crowded, so we waited outside.','Which punctuation joins two related independent clauses correctly?','The draft is ready; the editor will review it.',['The draft is ready, the editor will review it.','The draft is ready the editor will review it.','The draft is ready; because the editor will review it.'],'A semicolon can connect closely related independent clauses.','Repair "The instructions were unclear, we asked for help" using a connector that shows the relationship.',4),
('agreement','Subject–verb agreement','beginner','Match the verb to the head of the subject. A nearby plural noun inside a describing phrase does not make a singular subject plural.','The list of supplies is complete. List is singular.','Choose the correct sentence.','The purpose of these meetings is clear.',['The purpose of these meetings are clear.','The purposes of this meeting is clear.','The purpose of these meetings were clear.'],'The singular head purpose requires is in this present-tense sentence.','Write a sentence beginning "The value of these lessons" and complete it with an appropriate verb.',5),
('tense-consistency','Tense consistency','beginner','Keep the time frame clear. Tenses may change when the time changes, but an unexplained switch confuses the sequence.','Yesterday I revised the outline and checked the references. Both actions belong to yesterday.','Which sentence keeps its stated past time frame?','Last night, she drafted the paragraph and reviewed it.',['Last night, she drafts the paragraph and reviewed it.','Last night, she drafted the paragraph and reviews it.','Last night, she draft the paragraph and review it.'],'Drafted and reviewed both refer to the stated past period.','Describe two actions you completed yesterday in one sentence. Keep both verbs consistent with that time.',9),
('word-order','Clear word order','beginner','Put words near what they describe. Keep the main subject and verb easy to locate. Position only carefully because it can limit different parts of a sentence.','Only Mina submitted a draft means nobody else did. Mina submitted only a draft means she submitted nothing else.','Which sentence places only immediately before the submitted item?','Mina submitted only a draft.',['Only Mina submitted a draft.','Mina only submitted a draft.','Mina submitted a draft only to the editor.'],'Only directly before a draft limits the item submitted.','Write two sentences with only in different positions, then explain how their meanings differ.',15),
('modifiers','Misplaced and dangling modifiers','intermediate','An opening participial phrase should describe the subject that follows. Otherwise the sentence may appear to assign an action to an object.','Dangling: Walking to class, the rain soaked me. Clear: Walking to class, I was soaked by the rain.','Which sentence avoids a dangling modifier?','After reviewing the figures, the researcher corrected the table.',['After reviewing the figures, the table was corrected.','After reviewing the figures, several errors appeared.','After reviewing the figures, the report seemed clearer.'],'The researcher is the person who reviewed the figures.','Repair "After reading the instructions, the task became easier" by naming the person who read.',15),
('parallel-structure','Parallel structure','intermediate','Use matching grammatical forms for ideas presented as equals. Parallel structure helps readers recognize the relationship without reinterpreting the syntax.','The workshop teaches planning, drafting and revising. Each item is an -ing form.','Which list is parallel?','We aim to improve access, reduce delays and explain decisions.',['We aim to improve access, reducing delays and decisions explained.','We aim to improving access, reduce delays and explain decisions.','We aim to improve access, delays and explaining decisions.'],'The coordinated verbs improve, reduce and explain share the same to.','Rewrite "The programme encourages reading, to discuss ideas and revision" with matching forms.',20),
('clause-relationships','Cause, contrast and condition','intermediate','Choose a connector that expresses the intended logic. Because gives a reason; although introduces contrast; if introduces a condition. These relationships are not interchangeable.','If the library extends its hours, more evening study may be possible. This is conditional, not a promise.','Which connector introduces a condition?','if',['because','although','therefore'],'If sets a condition on the following claim.','Write three short sentences about a hypothetical study plan: one cause, one contrast and one condition.',19),
('transitions','Connectors and transitions','intermediate','A transition must match the relationship between ideas. However signals contrast; therefore signals a conclusion; for example introduces an illustration. Punctuation still needs to be correct.','The first route is shorter. However, the second route has fewer obstacles.','Which transition best signals an illustration?','for example',['nevertheless','therefore','in contrast'],'For example introduces an instance of the preceding general idea.','Write a general statement about a study habit and add an illustrative sentence with an appropriate transition.',19),
('concision','Concision and redundancy','intermediate','Remove words that repeat a meaning without removing necessary conditions or distinctions. Concision is faithful compression, not merely making a sentence shorter.','At this point in time can usually become now. A future possibility can often become a possibility.','Which revision keeps the meaning of "The reason for the delay is that the file is missing"?','The file is missing, causing the delay.',['The file is missing.','The delay is unreasonable.','The file was destroyed.'],'The revision retains both the missing file and its stated causal relationship to the delay.','Shorten "It is necessary for students to make a plan in advance before they begin" without losing its instruction.',22),
('precision','Clarity and precision','intermediate','Identify what vague words refer to. Replace a vague noun or pronoun when the context permits, but do not manufacture details the writer has not supplied.','Vague: This improved things. Clear, with known context: The new timetable reduced missed classes.','What should an editor do when "this" has no clear referent?','Ask which idea or action the writer means.',['Invent a likely policy.','Replace it with a statistic.','Assume the preceding person is meant.'],'Clarification preserves the writer’s meaning instead of inventing it.','Write a vague sentence with this or things, then replace the vague expression using only details you actually intend.',14),
('academic-tone','Word choice and academic tone','intermediate','Use accurate, proportionate wording. Formal writing does not require rare words or hostility. Avoid absolute labels when your evidence supports only a qualified criticism.','Overstated: The proposal is totally useless. Precise: The proposal does not address the stated implementation problem.','Which option offers a measured criticism?','The argument overlooks the cost of implementation.',['The argument is completely stupid.','Nobody could ever support the argument.','The argument proves that every reform fails.'],'The criticism identifies a specific limitation without personal insult or an unsupported universal claim.','Rewrite "This idea is really bad" as a specific criticism of a hypothetical idea, clearly stating the limitation.',23),
('causal-sentences','Expressing cause and effect','advanced','Separate an observed association from a causal explanation. State the proposed mechanism and relevant condition. Use can or may when the claim is conditional.','Hypothetical: If unclear instructions delay decisions, clarifying responsibilities may reduce that delay.','Which sentence makes a conditional causal claim?','Unclear responsibilities may delay decisions when approvals are required from several offices.',['Unclear responsibilities always destroy all institutions.','Two changes occurred together, so one must cause the other.','Decisions and responsibilities are the same thing.'],'The sentence proposes an outcome and a condition without claiming inevitability.','Construct a causal sentence about a hypothetical administrative delay. Include a mechanism and a qualification.',19),
('argumentative-sentences','Building an argumentative sentence','advanced','Make a defensible claim, give a relevant reason and indicate the condition under which it applies. A strong sentence does more than announce a preference.','A trial of extended study hours is worth considering if evening access is a barrier, because it would test whether access improves attendance.','Which sentence gives a claim supported by relevant reasoning?','The timetable should be reviewed because two compulsory classes currently overlap.',['The timetable should be reviewed because blue is a pleasant colour.','The timetable should be reviewed because it should be reviewed.','Everyone knows the timetable is wrong.'],'Overlapping compulsory classes is a relevant reason for reviewing a timetable.','Write a claim about a hypothetical classroom improvement and support it with one relevant reason.',24),
('analytical-sentences','Building an analytical sentence','advanced','Show how or why an outcome could arise. Name a mechanism, condition or competing explanation. Description tells what; analysis examines the relationship.','Hypothetical: A longer journey could reduce attendance by making punctual arrival harder, although class timing might also explain absences.','Which statement offers analysis rather than only description?','A fixed opening time may restrict access for students whose classes finish later.',['The library opens at a fixed time.','The library has a door.','Some students use the library.'],'It links opening time to a possible mechanism affecting a defined group.','Write one analytical sentence about a hypothetical access problem, including an alternative explanation.',24),
('qualification','Qualification without vagueness','advanced','A qualification states the scope or condition of a claim. It should make the statement more precise rather than weaken every verb with several uncertain expressions.','Hypothetical: The shorter route is preferable when travel time matters more than shelter.','Which statement has a clear condition?','The shorter route is preferable when both routes are equally safe.',['The shorter route is maybe perhaps sort of preferable.','The shorter route is always perfect for everyone.','The shorter route proves everything about travel.'],'The condition specifies the circumstances in which the comparison holds.','Make "Online discussion improves participation" into a qualified hypothesis without inventing supporting data.',10),
('transformation','Advanced sentence transformation','advanced','Change structure while preserving who acts, what is claimed, the time frame and qualifications. A passive construction or compressed clause must not strengthen the original claim.','Original: The team may finish the review if the missing files arrive. Equivalent: The review may be finished by the team if the missing files arrive.','Which revision preserves "The measure may reduce delays if staff receive training"?','With staff training, the measure may reduce delays.',['The measure will eliminate delays.','Training has already eliminated delays.','The measure reduces delays without any conditions.'],'May and the training condition remain; neither certainty nor timing is invented.','Transform a conditional sentence of your own into a different structure. Check that its qualification and meaning survive.',11),
]
S.append(('word-choice','Vocabulary and word choice','intermediate','Choose words for their meaning and natural use in context. Similar dictionary meanings do not make words interchangeable. Check what a replacement would add, remove or imply.','Effective concerns achieving an intended result; efficient concerns the resources used. A measure may be effective but costly. Decide which judgement you intend before choosing either word.','Which sentence preserves the meaning "These figures do not provide enough support for the claim"?','These figures are insufficient to support the claim.',['These figures disprove the claim.','These figures confirm the claim.','These figures are significant.'],'Insufficient means not enough. Lack of enough support does not establish that the opposite claim is true.','Write a sentence using effective or efficient. Explain the meaning you intend and test an alternative word against it.',23))
for row in S:
    id,title,level,rule,example,prompt,right,wrong,reason,task,day=row
    add('sentence',id,title,level,rule,example,prompt,right,wrong,reason,task,day)

R=[
('fact-opinion-argument', 'Fact, opinion and argument', 'beginner', 'A factual claim can be checked; an opinion expresses a judgement; an argument offers reasons for a conclusion. A factual-looking claim may still be unverified.', 'Hypothetical opinion: I prefer longer library hours. Argument: The library should trial longer hours because some classes end after it closes.', 'Which is an argument?', 'The timetable should change because two required classes overlap.', ['The timetable is convenient.', 'Two required classes overlap.', 'The timetable should change.'], 'The timetable proposal gives a conclusion and a relevant reason.', 'In a hypothetical school, distinguish a checkable statement, a personal preference and a reasoned proposal about its timetable. Write one of each. Label any factual-looking statement that you have not verified.', ['This is an evaluation without a supporting reason.', 'This is a checkable premise, but it does not itself state a proposal and supporting reason.', 'This states a conclusion without explaining why it should be accepted.']),
('central-claim', 'Finding a central claim', 'beginner', 'A central claim states what you want a reader to accept. Keep it specific enough to challenge and distinguish it from the topic.', 'Topic: classroom access. Claim: A trial evening session could improve access for students with late classes.', 'Which is a claim rather than only a topic?', 'The school should trial an evening study session.', ['Possible evening study arrangements.', 'Access for students whose classes end late.', 'The advantages of a study session.'], 'The sentence proposes a position that can be supported or challenged.', 'A hypothetical school has one unused room. State a specific proposal for using it, then distinguish your central claim from the general topic and from a reason supporting it.', ['This names a topic rather than taking a position.', 'This identifies an issue or group, but does not state what should be accepted.', 'This announces a discussion rather than a defensible position.']),
('supporting-reasons', 'Relevant supporting reasons', 'beginner', 'A reason supports a claim only when it helps explain why the conclusion should be accepted. A true but unrelated statement is not useful support.', 'Hypothetical: Repairing a broken light is relevant to safe evening use; the colour of the noticeboard is not.', 'Which reason directly connects repairing the light to seeing classroom material?', 'Students cannot read the board clearly in that room.', ['Repairing the light would be easier than changing the timetable.', 'The classroom is used by several subjects.', 'The room has recently been repainted.'], 'Visibility bears directly on the purpose of the repair.', 'A hypothetical classroom light is broken. Give one reason that connects repairing it to learning in that room. Contrast it with a genuine concern that does not establish that particular benefit.', ['Ease of implementation does not explain the visibility benefit being asked about.', 'Frequent use alone does not establish how the broken light affects seeing the material.', 'A room improvement does not explain why its lighting needs repair.']),
('logical-explanation', 'Explaining the link', 'beginner', 'Explain the link between the reason and the claim. Naming two ideas beside each other does not show why one supports the other.', 'Hypothetical: Moving a class avoids the overlap, so students can attend both required sessions.', 'Which sentence explains the reason–claim link?', 'Moving one class would remove the overlap and allow attendance at both.', ['Moving the class is the appropriate change because it should be moved.', 'The overlap is inconvenient, and the new timetable would look clearer.', 'Students favour the change, so it will remove every attendance difficulty.'], 'It names the mechanism by which the proposed change helps.', 'Suppose two required sessions overlap. Propose a scheduling change, then explain step by step how it would remove that specific barrier. State one condition under which your solution would still fail.', ['This restates the proposal rather than explaining how it helps.', 'Naming a problem and a different benefit does not explain the attendance mechanism.', 'Preference does not establish either the mechanism or that all barriers disappear.']),
('evidence-selection', 'Selecting evidence', 'beginner', 'Choose evidence that bears on the claim and has an identifiable source, date and scope. An illustrative example is not proof of a general claim.', 'To examine library access, collect opening times and actual student schedules; a fictional example only explains the question.', 'Which evidence is most directly relevant to a claimed timetable overlap?', 'The dated timetables for both required classes.', ['A dated timetable for only one of the two classes.', 'A teacher availability list without the scheduled class times.', 'Student opinions about whether the timetable is convenient.'], 'The actual timetables can establish whether those class times overlap.', 'Investigate a hypothetical claim that two required classes overlap. Name the actual records needed, their dates and what you would compare. Explain why preferences alone cannot establish their timing.', ['A comparison requires the relevant times of both classes.', 'Availability does not establish when those classes actually occur.', 'Opinions can identify a concern, but they do not directly establish the claimed overlap.']),
('premises-conclusions', 'Premises and conclusions', 'intermediate', 'Premises are the supporting statements; the conclusion is what they are meant to establish. Check whether accepting the premises really supports that conclusion.', 'All required classes must be attendable. Two required classes overlap. Therefore, the timetable needs review. This identifies a conflict, without proving a particular remedy.', 'What is the conclusion in that example?', 'The timetable needs review.', ['Two required classes overlap.', 'All required classes must be attendable.', 'Every class must move to the evening.'], 'Needs review is the judgement supported by the premises.', 'A hypothetical centre says all required workshops must be attendable, but two workshops overlap. Write the premises and the conclusion they support. Explain why these premises do not select one particular remedy.', ['This is a supporting premise, not the resulting judgement.', 'This is the standard used as a premise.', 'This particular remedy does not follow from the stated premises.']),
('assumptions', 'Identifying assumptions', 'intermediate', 'An assumption is a step your reasoning relies on without establishing it. Name it and ask what happens if it is false.', 'A longer opening period will help only if affected students can and wish to use it.', 'Which assumption directly connects evening hours to the affected students gaining access?', 'Affected students can use the proposed evening hours.', ['A longer opening period necessarily lowers the staffing cost.', 'Current morning users prefer the existing timetable.', 'A published notice is sufficient to remove every access barrier.'], 'Potential access depends on whether the relevant students can actually attend.', 'A hypothetical library proposes evening access. Identify an assumption linking the new hours to the intended users. Explain what observation would challenge it and how that would qualify your proposal.', ['A cost claim is not the access assumption, and a longer period does not establish lower cost.', 'Their preference does not establish whether the affected evening users can attend.', 'Information alone does not establish practical ability to use the proposed hours.']),
('causal-arguments', 'Cause-and-effect arguments', 'intermediate', 'A causal argument needs a mechanism, timing and consideration of alternative causes. Events occurring together do not by themselves establish causation.', 'Hypothetical: If unclear approval responsibility delays a task, naming a responsible officer may reduce that delay.', 'Why is "attendance rose after the notice, so the notice caused the rise" incomplete?', 'Other changes could explain the rise.', ['The order of events already identifies the notice as the cause.', 'A plausible explanation is sufficient without checking competing changes.', 'The attendance increase itself shows which change produced it.'], 'The sequence is compatible with causation but does not exclude other explanations.', 'Suppose attendance improves after a hypothetical schedule change. Explain a possible mechanism, identify a competing explanation and describe evidence that could distinguish them. Treat the improvement as part of the scenario, not a real finding.', ['Earlier occurrence is compatible with causation but does not exclude other causes.', 'A mechanism needs assessment, not just plausibility.', 'An outcome alone cannot identify one cause among several possible changes.']),
('fallacies', 'Recognising common fallacies', 'intermediate', 'A personal attack does not refute reasoning. A false dilemma excludes alternatives without justification. Circular reasoning restates the claim as its reason.', 'Circular: This plan is best because no plan is better. That supplies no independent support.', 'Which statement is circular?', 'The rule is justified because it is a justified rule.', ['The rule is justified because the administrator favours it.', 'The rule needs review because it conflicts with another requirement.', 'The rule is justified because its wording is polished.'], 'The reason merely repeats the conclusion.', 'For a hypothetical school policy, write examples of a personal attack, a false dilemma and circular reasoning. Explain the fault in each, then replace one faulty reason with independent relevant support.', ['This appeals to a person rather than simply restating the conclusion; it is not the circular example.', 'This supplies a distinct reason that can be examined.', 'This substitutes presentation for support, rather than repeating the conclusion.']),
('irrelevant-arguments', 'Weak and irrelevant arguments', 'intermediate', 'Separate a reason that fails from a conclusion that may still be true. Rejecting one bad argument does not automatically prove the opposite conclusion.', 'An irrelevant colour preference does not support extending library hours, but it does not prove that hours should remain unchanged.', 'What follows when a reason is irrelevant?', 'That reason does not support the claim.', ['The opposite claim is established by the failure of this reason.', 'No other reason could support the claim.', 'More confident wording would make the reason support the claim.'], 'Failure of support is not proof of the opposite position.', 'Someone supports extending a hypothetical library timetable with an irrelevant reason. Explain why that reason fails without declaring the proposal false. Give a separate relevant reason that still needs verification.', ['Failure of one support does not establish the opposite claim.', 'One irrelevant reason does not exclude different relevant evidence.', 'Confidence does not repair the lack of logical relevance.']),
('counterarguments', 'Constructing a counterargument', 'advanced', 'Present a serious opposing reason in a form an informed opponent might accept. Do not make the opposing view weaker for convenience.', 'A concern about longer library hours could be staffing cost and the reliability of supervision.', 'Which counterargument engages an access proposal seriously?', 'Longer hours may require staffing resources that are unavailable.', ['Longer hours could give late-class students more access.', 'The proposal is attractive because learning matters.', 'The school can decide how to advertise the new hours.'], 'It identifies a practical constraint relevant to the proposal.', 'Defend a hypothetical evening study session, then formulate the strongest reasonable objection about staffing or equitable access. Explain the objection in terms its proponent could accept before attempting a reply.', ['This supports the proposal rather than raising a counterargument.', 'A favourable general statement does not engage an opposing constraint.', 'Advertising does not address whether the required staffing exists.']),
('rebuttal', 'Responding with a rebuttal', 'advanced', 'Answer the actual opposing reason. Concede what is valid, show what evidence is needed and explain why your position remains defensible under stated conditions.', 'A limited trial could test demand within an agreed staffing budget; it cannot guarantee that costs disappear.', 'Which reply addresses a staffing-cost objection?', 'Trial limited hours within a stated budget, then compare demand and cost.', ['Present the educational benefits again without discussing staffing.', 'Treat expressed demand as proof that staffing can be funded.', 'Promise that efficiency will cover the cost without checking the budget.'], 'The reply directly addresses the constraint and proposes a test rather than inventing savings.', 'A hypothetical digital study tool is challenged on privacy grounds. State the objection fairly, concede a valid concern and propose a bounded response. Explain what handling or retention evidence must be checked before adoption.', ['Repeating benefits leaves the cost objection unanswered.', 'Demand and available funding are different matters.', 'An unverified saving does not answer the resource constraint.']),
('nuance', 'Qualification and nuance', 'advanced', 'State where your claim applies and where it may fail. A qualified claim can be stronger because its scope matches its reasons and evidence.', 'A trial is defensible if supervision and staffing are available; otherwise another access arrangement may be preferable.', 'Which claim is appropriately qualified?', 'A trial may be useful where staffing and demand justify it.', ['A trial is worthwhile whenever any demand exists, regardless of resources.', 'No conclusion can be reached until every uncertainty is eliminated.', 'A successful trial in one setting establishes success in every setting.'], 'The qualification connects the claim to relevant conditions.', 'Develop a qualified claim about a hypothetical distance-learning option. State who might benefit, the access conditions required and a case in which your claim would not apply. Do not invent results.', ['Demand alone does not satisfy the stated staffing condition.', 'Qualification permits a bounded judgement despite remaining uncertainty.', 'A limited observation cannot establish universal applicability.']),
('argument-paragraph', 'Developing an argumentative paragraph', 'advanced', 'Organise a paragraph around one claim, explain the reason, identify suitable evidence and relate it back to the claim. Avoid a list of disconnected slogans.', 'Plan: claim about access → mechanism → evidence needed → limitation → qualified conclusion. This is a structure, not a supplied argument.', 'Which item should explain why evidence supports the claim?', 'The reasoning linking the evidence to the claim.', ['A second claim stated immediately after the evidence.', 'A repetition of the evidence in stronger wording.', 'A source label without explaining its relevance.'], 'Readers need the inferential connection, not merely a pasted fact.', 'Write one hypothetical policy paragraph with a controlling claim, a supporting reason, an explicit evidence need and a qualification. Explain the inferential role of each part instead of adding an unsupported quotation.', ['Another claim does not explain how the evidence supports the first one.', 'Repetition does not provide the inferential connection.', 'Attribution matters, but a label alone does not explain the evidence–claim link.']),
('argument-evaluation', 'Evaluating a complete argument', 'advanced', 'Review relevance, clarity, logical consistency, reasoning, evidence, alternatives, rebuttal and coherence. These instructional criteria are not examiner marks.', 'A defensible argument may still need better evidence; do not confuse fluent language with a sound inference.', 'Which review is most useful?', 'Identify a specific inference or evidence gap and explain how to test it.', ['Treat a supplied reference as verified without examining its source.', 'Correct the vocabulary and assume the reasoning is therefore sound.', 'Count supporting statements without checking whether they are relevant.'], 'Specific criticism helps the writer revise a real weakness.', 'Evaluate your own hypothetical argument: identify its weakest inference, an unsupported premise and a serious alternative. Revise the argument to address one weakness while retaining any unresolved limitation. Use qualitative criticism, not examination marks.', ['A reference must be checked before it is accepted as reliable support.', 'Language improvement alone does not validate the inference.', 'The number of statements does not establish the quality of their support.']),
]
for id,title,level,rule,example,prompt,right,wrong,reason,task,wrong_feedback in R:
    add('argument',id,title,level,rule,example,prompt,right,wrong,reason,task,wrong_feedback=wrong_feedback)

A=[
('description-analysis', 'Description and analysis', 'beginner', 'Description states what happens. Analysis examines how, why or under what conditions it happens. Neither permits inventing evidence.', 'Description: A school uses an online form. Analysis question: How could the form change the time needed to process a request?', 'Which question is analytical?', 'How might the form alter processing time?', ['Which fields does the form contain?', 'How many requests were entered?', 'When was the form introduced?'], 'It asks about a mechanism connecting a change to an outcome.', 'A hypothetical office replaces a paper request form with an online form. First describe the change. Then ask and answer a mechanism question about processing time, clearly distinguishing a hypothesis from established evidence.', ['This asks for a description of its contents.', 'A count describes activity; it does not by itself explain how the form changes processing time.', 'A date describes timing without examining the proposed mechanism.']),
('causes-effects', 'Causes and consequences', 'beginner', 'Separate a proposed cause from its consequences. Explain the intermediate steps, then identify what would need checking.', 'Hypothetical chain: unclear instructions → repeated queries → delayed completion. Each link needs evidence.', 'What should be added to a list of causes?', 'An explanation of how each could produce the outcome.', ['A longer list of causes without explaining the links.', 'A decision that whichever cause is listed first must be strongest.', 'A description of the outcome repeated after each cause.'], 'Analysis explains links rather than merely naming possible causes.', 'Analyse a hypothetical sequence of unclear instructions, repeated queries and delayed completion. Explain each proposed link, identify a point where the sequence could fail and name observations needed to test it.', ['Adding names does not show how a cause produces the outcome.', 'List order does not establish causal importance.', 'Repeating the outcome does not explain the intermediate steps.']),
('variable-relationships', 'Relationships between variables', 'beginner', 'A variable is a quantity or characteristic that can differ. Ask how a change in one might relate to another, and whether conditions alter that relationship.', 'Hypothetical variables: travel time and attendance. A relationship could differ with transport reliability.', 'Which pair contains the proposed explanatory variable and outcome in the travel-and-attendance example?', 'Travel time and attendance.', ['Travel time and transport reliability.', 'Attendance and the date a register was copied.', 'Transport reliability and journey duration.'], 'The pair allows a relationship to be examined rather than assumed.', 'Consider travel time and class attendance in a hypothetical school. Identify the proposed explanatory variable, the outcome and a condition such as transport reliability. Explain why the proposed relationship still needs evidence.', ['Reliability is a possible condition; this pair omits the attendance outcome.', 'This pair includes the outcome but not the proposed travel-time explanatory variable.', 'This pair examines transport conditions but omits the stated attendance outcome.']),
('analysis-assumptions', 'Recognising assumptions', 'beginner', 'Identify a step taken for granted. Ask whether it is necessary and what evidence could support or challenge it.', 'An online service helps only if users have the access and skills needed to use it.', 'What assumption underlies a claim that online forms improve everyone’s access?', 'Everyone concerned can access and use the form.', ['The office prefers receiving online requests.', 'The form has fewer fields than the previous version.', 'People who already use online services prefer the form.'], 'The universal claim relies on access and usability, which need checking.', 'A hypothetical office claims its online form improves access for everyone. Identify what this assumes about access and skills. Describe a counterexample and explain how it would narrow the claim.', ['An institutional preference does not establish access for every user.', 'A shorter form does not establish that all users can access and use it.', 'The views of existing users do not establish the circumstances of everyone concerned.']),
('evidence-quality', 'Evaluating evidence', 'beginner', 'Consider source, date, method, population and relevance. A small self-selected response does not automatically represent everyone.', 'A voluntary class survey may reveal respondents’ views but cannot alone establish the whole school’s preferences.', 'What limitation should be noted for a voluntary survey?', 'Respondents may differ from nonrespondents.', ['A large response count automatically makes the sample representative.', 'Written answers establish that preferences will remain unchanged.', 'Using one question guarantees that everyone is equally likely to respond.'], 'Selection can affect what the findings represent.', 'Review a hypothetical voluntary survey about a study service. Identify its population, how participants joined and whose views could be missing. State what it can suggest and what it cannot establish about all students.', ['Sample size does not by itself resolve self-selection.', 'Recording current views does not establish their future stability.', 'A common question does not guarantee equal participation.']),
('competing-explanations', 'Competing explanations', 'intermediate', 'Develop plausible alternatives and ask what observations could distinguish them. Do not list alternatives and then ignore them.', 'Absence could relate to travel, class timing or illness; different records would help distinguish these explanations.', 'What makes an alternative explanation useful?', 'A clear prediction that can be compared with observations.', ['Compatibility with one observation, without distinguishing the rival explanation.', 'Agreement with the explanation the writer already prefers.', 'A broader label that cannot be checked against any observation.'], 'A discriminating prediction helps test competing explanations.', 'Suppose a hypothetical office has long queues. Compare a staffing explanation with an approval-rule explanation. Identify an observation that would favour one over the other, rather than merely listing both.', ['Both explanations may fit that observation; a useful test distinguishes them.', 'Preference does not make an alternative informative.', 'An untestable label cannot help distinguish the proposed causes.']),
('correlation-causation', 'Correlation and causation', 'intermediate', 'Association does not establish causal direction or exclude a third factor. Examine mechanism, sequence and competing explanations.', 'Two outcomes might both change after a timetable revision; this does not alone show that one caused the other.', 'What could explain an observed association besides direct causation?', 'A third factor affecting both variables.', ['The stronger association must identify the direction of causation.', 'The first measured variable must cause the second one.', 'The association rules out a factor affecting both variables.'], 'A common cause can produce association without direct causation between the measured variables.', 'In a hypothetical school, attendance and punctuality both improve during one term. Examine direct causation, reverse causation and a possible common cause. Describe what timing or comparison evidence would be needed before attributing an effect.', ['Strength alone does not establish causal direction.', 'The order of measurement does not establish the order of causes.', 'Association does not rule out a common cause.']),
('institutional-factors', 'Institutional and structural factors', 'intermediate', 'Look beyond individual intention to rules, resources, responsibilities and incentives. These factors are possible explanations, not excuses or automatic causes.', 'A request may wait because no office has a clear approval responsibility, even when individuals want to help.', 'Which is an institutional factor?', 'The rule assigning approval responsibility.', ['One applicant feels frustrated by waiting.', 'An officer personally hopes to finish the task quickly.', 'The observer thinks the building looks inefficient.'], 'The rule governs how the institution processes decisions.', 'A hypothetical permit request passes between offices without a decision. Analyse responsibilities, rules and resources separately from individual intentions. Explain one proposed mechanism and the records needed to test it.', ['This describes a personal response rather than the institutional rule asked about.', 'An intention does not specify the allocation of institutional responsibility.', 'An impression of the building does not identify an operating institutional factor.']),
('dimensions', 'Analysing multiple dimensions', 'intermediate', 'Choose dimensions relevant to the issue: resources, implementation, distribution, incentives or rights. More headings do not help unless each affects the reasoning.', 'A hypothetical education initiative can be examined for access, teaching capacity, cost and unequal effects.', 'When should a dimension be included?', 'When it changes an explanation, consequence or judgement.', ['When it supplies another heading, even without affecting the argument.', 'When it repeats an existing dimension under a new label.', 'When it produces the longest section in the response.'], 'Relevant dimensions deepen reasoning; unrelated headings add clutter.', 'Examine a hypothetical proposal for a community learning centre. Select three relevant dimensions, such as access, staffing and distribution of benefits. Explain how each changes the judgement and exclude one tempting but irrelevant heading.', ['A heading adds no analytical value without a relevant relationship.', 'Relabelling the same issue does not add an independent dimension.', 'Length does not establish relevance to the issue.']),
('time-horizons', 'Short- and long-term implications', 'intermediate', 'Separate immediate effects from effects that depend on adaptation, maintenance or changed incentives. State uncertainty about future outcomes.', 'A new system may take training time now and might reduce repeated work later; both claims need evidence.', 'Which comparison distinguishes time horizons?', 'Initial training costs versus possible later processing gains.', ['The initial training schedule versus another description of that same schedule.', 'Possible future gains treated as evidence that training has no present cost.', 'An assumption that implementation effects remain identical over time.'], 'It compares immediate demands with outcomes that could emerge later.', 'Analyse a hypothetical switch to digital record handling. Separate immediate training demands from possible later changes in repeated work. Identify a maintenance condition and explain why the longer-term outcome remains uncertain.', ['These concern the same immediate activity rather than different time horizons.', 'A future possibility does not erase an immediate demand.', 'This assumes away the adaptation that a time-horizon comparison should examine.']),
('trade-offs', 'Identifying trade-offs', 'advanced', 'A trade-off arises when improving one objective can constrain another. Explain what is gained, what may be lost and who bears the consequences.', 'Longer opening hours may improve access but require more staffing or a narrower range of services.', 'Which question tests a trade-off?', 'What other service might lose resources if hours are extended?', ['How many favourable comments does the proposal receive?', 'Can every benefit be counted while leaving the budget unchanged?', 'Would a clearer announcement make the proposal more appealing?'], 'It examines an opportunity cost relevant to the decision.', 'A hypothetical centre has a fixed staffing budget. Compare extending opening hours with increasing support during existing hours. Explain the opportunity cost, who gains or loses and what evidence would change your preference.', ['Popularity does not identify the resources or services sacrificed.', 'Counting benefits alone does not examine the resource constraint.', 'Communication does not identify the competing use of staffing resources.']),
('counterfactuals', 'Counterfactual thinking', 'advanced', 'A counterfactual asks what might happen without the proposed cause or intervention. It helps distinguish the effect of a change from an existing trend.', 'To assess a new timetable, ask how attendance might have changed under the previous timetable over the same period.', 'What is the relevant counterfactual?', 'Attendance during that period if the timetable had not changed.', ['Attendance before the change, regardless of the trend during the later period.', 'Attendance after the change, without a comparison.', 'The announced attendance target for the new timetable.'], 'The comparison concerns the outcome in the absence of the change.', 'A hypothetical school introduces a new timetable during a term when attendance was already changing. Specify the relevant outcome without that change, explain why the before–after comparison may mislead and propose a cautious comparison strategy.', ['A previous period alone may not represent what would have happened during the same later period.', 'The observed outcome alone does not describe the absence of the change.', 'An intended target is not the outcome that would occur without the intervention.']),
('solution-comparison', 'Comparing proposed solutions', 'advanced', 'Apply consistent criteria such as feasibility, cost, access and unintended effects. State the evidence and assumptions behind each comparison.', 'Compare a later opening time with an evening trial using the same access and staffing criteria.', 'What makes a comparison fair?', 'Using the same relevant criteria for both options.', ['Using a different favourable criterion for each preferred option.', 'Ranking the options by the number of benefits their supporters name.', 'Assessing only the preferred option against the main implementation constraint.'], 'Consistent criteria let the reader assess the trade-off.', 'Compare two hypothetical ways to improve access: later in-person hours and an online alternative. Use the same relevant criteria for both. Distinguish known constraints from assumptions and explain a conditional preference without inventing costs.', ['Changing criteria prevents a consistent comparison.', 'A count of claimed benefits does not evaluate comparable effects or constraints.', 'The competing option must also be assessed against relevant criteria.']),
('balanced-conclusions', 'Balanced conclusions', 'advanced', 'A balanced conclusion weighs the evidence rather than giving equal weight to every view. State the most defensible judgement and the conditions or uncertainty that remain.', 'A limited trial may be preferable if supervision is feasible; otherwise a different arrangement needs consideration.', 'Which conclusion is appropriately bounded?', 'The trial is defensible if the staffing condition can be met.', ['The trial must be adopted because it has at least one possible benefit.', 'The trial must be rejected until no uncertainty remains.', 'Both options deserve equal weight merely because two views were presented.'], 'It takes a position while retaining a relevant condition.', 'Consider a hypothetical trial with possible access benefits but unresolved supervision constraints. Reach a bounded judgement, identify the strongest remaining objection and state what evidence could change your conclusion.', ['A possible benefit does not resolve the relevant constraint.', 'A bounded judgement can be possible before every uncertainty disappears.', 'Balance depends on the quality of support, not counting viewpoints.']),
('analytical-paragraph', 'Constructing an analytical paragraph', 'advanced', 'Develop a controlling judgement, explain a mechanism, examine an alternative, state evidence needs and reach a qualified conclusion. A list of facts is insufficient.', 'Outline only: issue → mechanism → competing explanation → evidence needed → conditional judgement. The writer supplies the analysis.', 'Which element changes a descriptive list into analysis?', 'Explaining and testing relationships between the observations.', ['Arranging the observations chronologically without explaining their links.', 'Adding a quotation without examining its relevance to the mechanism.', 'Giving each observation a separate heading without comparing explanations.'], 'Analysis depends on reasoned relationships and evidence, not length.', 'Write a hypothetical paragraph about delays in processing study-service requests. Explain a mechanism, contrast a competing cause, identify a discriminating observation and reach a qualified judgement. Make the connections explicit rather than listing facts.', ['Sequence helps description, but it does not by itself explain or test a relationship.', 'A quotation cannot replace the causal or inferential link.', 'Headings do not supply the missing analytical connections.']),
]
for id,title,level,rule,example,prompt,right,wrong,reason,task,wrong_feedback in A:
    add('analysis',id,title,level,rule,example,prompt,right,wrong,reason,task,wrong_feedback=wrong_feedback)

package=dict(version='skills-2026-10-v2',attribution='Original bounded CSS Vista skills teaching. Hypothetical examples are not evidence of real events. Grammar rules link to the existing course.',lessons=LESSONS)
target=ROOT/'public/api/_premium_files/skills-curriculum.json'
encoded=json.dumps(package,ensure_ascii=False,indent=2)+'\n'
assert len(LESSONS)==51 and len({x['id'] for x in LESSONS})==51
assert all(len(x['check']['options'])==4 and len(set(x['check']['options']))==4 for x in LESSONS)
if '--check' in sys.argv:
    assert target.read_text()==encoded,'Curriculum differs from its authored source'
else:
    target.parent.mkdir(parents=True,exist_ok=True);target.write_text(encoded)
print('Verified 51 original skills lessons: 21 sentence, 15 argumentation, 15 analysis; unique IDs and four-option fixed checks.')
